import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().start();
    }

    void start() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[in.nextInt()] = 1;
        }
        int[] res = {1};
        int exp = n / 2;
        while (true) {
            if ((exp & 1) == 1) {
                res = multiply(res, v, 998244353);
            }
            exp >>= 1;
            if (exp == 0) break;
            v = multiply(v, v, 998244353);
        }
        long total = 0;
        for (int val : res) {
            total = (total + (long) val * val) % 998244353;
        }
        out.println(total);
        out.close();
    }

    static int[] multiply(int[] a, int[] b, int mod) {
        int needed = a.length + b.length - 1;
        int size = 1;
        while (size < needed) size <<= 1;

        double[] ar = new double[size], ai = new double[size];
        for (int i = 0; i < a.length; i++) {
            long x = ((a[i] % mod) + mod) % mod;
            ar[i] = x & 0x7FFF;
            ai[i] = x >>> 15;
        }
        fft(ar, ai, false);

        double[] br = new double[size], bi = new double[size];
        for (int i = 0; i < b.length; i++) {
            long x = ((b[i] % mod) + mod) % mod;
            br[i] = x & 0x7FFF;
            bi[i] = x >>> 15;
        }
        fft(br, bi, false);

        double[] cr1 = new double[size], ci1 = new double[size];
        double[] cr2 = new double[size], ci2 = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);
            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;
            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            cr1[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            ci1[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            cr2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            ci2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(cr1, ci1, true);
        fft(cr2, ci2, true);

        int[] out = new int[needed];
        for (int i = 0; i < needed; i++) {
            long aa = Math.round(cr1[i]);
            long bb = Math.round(cr2[i]);
            long cc = Math.round(ci1[i]);
            out[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return out;
    }

    static void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j & bit) != 0; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            double ang = 2 * Math.PI / len * (inv ? -1 : 1);
            double wRe = Math.cos(ang), wIm = Math.sin(ang);
            for (int i = 0; i < n; i += len) {
                double wr = 1, wi = 0;
                for (int j = 0; j < len / 2; j++) {
                    double ur = re[i + j], ui = im[i + j];
                    double vr = re[i + j + len / 2] * wr - im[i + j + len / 2] * wi;
                    double vi = re[i + j + len / 2] * wi + im[i + j + len / 2] * wr;
                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + len / 2] = ur - vr;
                    im[i + j + len / 2] = ui - vi;
                    double tmp = wr * wRe - wi * wIm;
                    wi = wr * wIm + wi * wRe;
                    wr = tmp;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream in) { this.in = in; }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[ptr++] & 0xFF;
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            int s = 1;
            if (c == '-') { s = -1; c = read(); }
            int x = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                x = x * 10 + c - '0';
                c = read();
            } while (c > 32);
            return x * s;
        }
    }
}
